content+=section('<div class="reading"><label class="sr-only" for="faq-search">Search questions and answers</label><div class="searchbox"><input id="faq-search" type="search" placeholder="Search a question, like ‘online’ or ‘teach’" autocomplete="off"></div><p id="faq-count" aria-live="polite">17 answers</p>'+faq(FAQ)+'<p id="faq-empty" hidden>No answers match that search. Try a different word or contact support.</p><div class="note">Still need a hand? <a href="mailto:support@talent-share.com">Contact support</a> and tell us what you are trying to do.</div></div>')
