try:
 from bs4 import BeautifulSoup
 output=['# talent-share website content\n','Editorial / Modernist with restrained neobrutalist accents. Existing TalentShare logo and violet brand family.\n','Static marketing and subject-guide content. Program listings, teacher profiles, prices, dates, enrollments, and account workflows remain at app.talent-share.com.\n']
 for p in pages:
  output+=[f'\n## {p["path"]}\n',f'Title tag: {p["title"]}\n\nMeta description: {p["description"]}\n\nPrimary keyword: {p["primary_keyword"]}\n']
  soup=BeautifulSoup(p['html'],'html.parser')
  for el in soup.select('h1,h2,h3,p,summary,li'):
   text=el.get_text(' ',strip=True)
   if text: output.append(('\n'+('#'*int(el.name[1])+ ' ' if el.name.startswith('h') else '')+text+'\n'))
 (ROOT.parent/'TalentShare-Website-Content.md').write_text('\n'.join(output))
except ImportError:pass
print(f'Built {len(pages)} static pages into {OUT}')
from html.parser import HTMLParser
class CopyParser(HTMLParser):
 def __init__(self):super().__init__();self.lines=[];self.parts=[];self.tag=None
 def handle_starttag(self,tag,attrs):
  if tag in ['h1','h2','h3','p','summary','li'] and self.tag is None:self.tag=tag;self.parts=[]
  if tag=='br' and self.tag:self.parts.append(' ')
 def handle_data(self,data):
  if self.tag:self.parts.append(data)
 def handle_endtag(self,tag):
  if tag==self.tag:
   text=''.join(self.parts).strip()
   if text:self.lines.append((('#'*int(tag[1])+' ') if tag.startswith('h') else ('- ' if tag=='li' else ''))+text)
   self.tag=None
